class Tee:
    def __init__(self, path):
        self.f = open(path, "a")
        self.stdout = sys.stdout

    def write(self, s):
        self.stdout.write(s)
        self.f.write(s)

    def flush(self):
        self.stdout.flush()
        self.f.flush()


sys.stdout = Tee(LOG)


