def reshape_group(df, name, n0, n1):
    """Sort + reshape, then verify against pivot_table."""
    g = df[df["dataset_path"] == name].sort_values(["index_0", "index_1"])
    assert len(g) == n0 * n1, (name, len(g), n0, n1)
    assert np.array_equal(g["index_0"].to_numpy(), np.repeat(np.arange(n0), n1))
    assert np.array_equal(g["index_1"].to_numpy(), np.tile(np.arange(n1), n0))
    A = g["value"].to_numpy().reshape(n0, n1)
    B = (df[df["dataset_path"] == name]
         .pivot_table(index="index_0", columns="index_1", values="value").to_numpy())
    assert A.shape == B.shape and np.allclose(A, B, rtol=0, atol=0), name
    return A


