def dense_ref(E, mode):
    """Reference dense magnitude panel for a CoefLeg energy.
    mode 'nearest'  : nearest 0.1 eV panel (matches the original script's argmin)
    mode 'interp'   : linear interpolation between the bracketing 0.1 eV panels
    """
    if mode == "nearest":
        j = int(np.argmin(np.abs(E_EXP - E)))
        return j, MAG[j]
    # bracketing
    if E <= E_EXP[0]:
        return 0, MAG[0]
    if E >= E_EXP[-1]:
        return len(E_EXP) - 1, MAG[-1]
    hi = int(np.searchsorted(E_EXP, E, side="left"))
    lo = hi - 1
    if abs(E_EXP[lo] - E) < 1e-12:
        return lo, MAG[lo]
    w = (E - E_EXP[lo]) / (E_EXP[hi] - E_EXP[lo])
    return lo, (1.0 - w) * MAG[lo] + w * MAG[hi]


# ----------------------------------------------------------------------------
# 1. Independent spherical-harmonic machinery
# ----------------------------------------------------------------------------
def plm_recurrence(L, M, x):
    """P_L^M(x) with NO Condon-Shortley phase, by explicit recurrence."""
    if M < 0 or M > L:
        return np.zeros_like(x)
    pmm = np.ones_like(x)
    if M > 0:
        somx2 = np.sqrt(np.maximum(0.0, (1.0 - x) * (1.0 + x)))
        fact = 1.0
        for _ in range(M):
            pmm = pmm * fact * somx2
            fact += 2.0
    if L == M:
        return pmm
    pmmp1 = x * (2 * M + 1) * pmm
    if L == M + 1:
        return pmmp1
    pll = pmmp1
    for LL in range(M + 2, L + 1):
        pll = ((2 * LL - 1) * x * pmmp1 - (LL + M - 1) * pmm) / (LL - M)
        pmm, pmmp1 = pmmp1, pll
    return pll


from scipy.special import lpmv  # only used for the cross-check below

_maxdev = 0.0
for L in range(9):
    for M in range(L + 1):
        mine = plm_recurrence(L, M, CTH)
        ref = lpmv(M, L, CTH) * ((-1.0) ** M)      # scipy includes the CS phase
        _maxdev = max(_maxdev, float(np.max(np.abs(mine - ref))))
say("recurrence vs scipy.lpmv (no-CS convention): max abs dev = %.3e" % _maxdev)


def Plm(L, M, cs=True, normed=True, sq2=True):
    """Same convention grid as the package: CS phase / Y normalisation / sqrt(2)."""
    if M > L or L < 0:
        return np.zeros_like(CTH)
    v = plm_recurrence(L, M, CTH)
    if cs and M > 0:
        v = v * ((-1.0) ** M)
    if normed:
        v = v * math.sqrt((2 * L + 1) / (4.0 * math.pi)
                          * math.factorial(L - M) / math.factorial(L + M))
    if M > 0 and sq2:
        v = v * math.sqrt(2.0)
    return v


def polyfit_r2(rec, y):
    """R2 of the best affine fit, via numpy.polyfit (different route)."""
    c = np.polyfit(rec, y, 1)
    p = np.polyval(c, rec)
    return float(1.0 - ((y - p) ** 2).sum() / ((y - y.mean()) ** 2).sum())


def corr2(rec, y):
    return float(np.corrcoef(rec, y)[0, 1] ** 2)


READ_A = [(1, 0, 0), (3, 2, 0), (5, 2, 1), (7, 2, 2), (9, 1, 1)]   # (col, L, M)
READ_B = [(1, 0), (3, 0), (5, 1), (7, 2), (9, 1)]                   # (col, m), L = k

CONV = [(cs, nm, s2) for cs in (True, False) for nm in (True, False) for s2 in (True, False)]


def reconstruct(E, reading, cs, normed, sq2):
    b = BLOCKS[E]
    if reading == "A":
        return sum(b[k, c] * Plm(L, M, cs, normed, sq2)
                   for c, L, M in READ_A for k in range(9))
    return sum(b[k, c] * Plm(k, m, cs, normed, sq2)
               for c, m in READ_B for k in range(9))


