def dme_dict(E):
    d = DME[E]
    z = np.concatenate([[d[r, 2], d[r, 3]] for r in range(7)])
    return np.array([z[i] * z[j] for i in range(14) for j in range(i, 14)])


DIC = np.array([dme_dict(E) for E in CE_EV])       # 13 x 105
RANK_DIC = int(np.linalg.matrix_rank(DIC))
